// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 d, uint256 v) public {
        vm.assume(d <= VALUE_CAP);
        // WIDE domain: fuzz both the funding amount and the withdrawal amount.
        d = bound(d, 1, 1 ether);
        vm.deal(address(this), d);
        // fund c through its payable fallback (depositsCount increments)
        (bool dep, ) = address(c).call{value: d}("");
        assertTrue(dep);

        // v may equal anything up to the full balance; the bug shows for any v < d
        v = bound(v, 0, d);

        vm.prank(address(this)); // this contract is the owner (deployer)
        c.withdraw(v);

        // Rule: after withdraw(v) the contract retains exactly d - v wei.
        assertTrue(address(c).balance == d - v);
    }

    receive() external payable {}
}
